function mctFromLeafValues(arr) {
  const n = arr.length;
  const maxLeaf = Array.from({ length: n }, () => new Array(n).fill(0));
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let i = 0; i < n; i++) {
    maxLeaf[i][i] = arr[i];
    for (let j = i + 1; j < n; j++) {
      maxLeaf[i][j] = Math.max(maxLeaf[i][j - 1], arr[j]);
    }
  }

  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      dp[i][j] = Infinity;
      for (let mid = i; mid < j; mid++) {
        const root = maxLeaf[i][mid] * maxLeaf[mid + 1][j];
        dp[i][j] = Math.min(dp[i][j], dp[i][mid] + dp[mid + 1][j] + root);
      }
    }
  }
  return dp[0][n - 1];
}

brute:
function mctFromLeafValues(arr) {
  // Build the tree bottom-up by repeatedly joining two neighbouring subtrees, trying every order.
  // Each subtree is represented by its largest leaf; joining a and b costs a * b.
  const memo = new Map();
  const best = (list) => {
    if (list.length === 1) return 0;
    const key = list.join(',');
    if (memo.has(key)) return memo.get(key);
    let result = Number.MAX_SAFE_INTEGER;
    for (let p = 0; p + 1 < list.length; p++) {
      const joined = [...list.slice(0, p), Math.max(list[p], list[p + 1]), ...list.slice(p + 2)];
      result = Math.min(result, list[p] * list[p + 1] + best(joined));
    }
    memo.set(key, result);
    return result;
  };
  return best(arr);
}

