function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const n = size === 'large' ? 30 + pick(11) : 2 + pick(7);
  const top = rand() < 0.3 ? 1 + pick(4) : 15;
  return [Array.from({ length: n }, () => 1 + pick(top))];
}
